 * Parser for the configuration document format described in the task.
 * Produces a tree of nodes (see below) or throws a ParseError carrying the
 * line number and a short reason string, matching the CLI's error format.
 */

export class ParseError extends Error {
  constructor(line, reason) {
    super(reason)
    this.line = line
    this.reason = reason
  }
}

function fail(line, reason) {
  throw new ParseError(line, reason)
}

// --- node constructors -----------------------------------------------------

function makeTable(explicit) {
  return { kind: 'table', explicit, entries: new Map() }
}

function makeArrayOfTables() {
  return { kind: 'array-of-tables', items: [] }
}

function makeArray() {
  return { kind: 'array', items: [] }
}

function makeScalar(kind, value) {
  return { kind, value }
}

// --- character helpers -------------------------------------------------

function isSpace(c) {
  return c === ' ' || c === '\t'
}

function isNameChar(c) {
  return c !== undefined && /[A-Za-z0-9_-]/.test(c)
}

function isDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function atLineEnd(line, pos) {
  if (pos >= line.length) return true
  const c = line[pos]
  return c === '#' || c === ';'
}

// --- a cursor over a single line -------------------------------------------

class Cursor {
  constructor(line, pos, lineNo) {
    this.line = line
    this.pos = pos
    this.lineNo = lineNo
  }

  skipWs() {
    while (isSpace(this.line[this.pos])) this.pos++
  }

  atEnd() {
    return atLineEnd(this.line, this.pos)
  }

  peek() {
    return this.line[this.pos]
  }

  fail(reason) {
    fail(this.lineNo, reason)
  }
}

// --- quoted strings ----------------------------------------------------

function scanBasicString(cur) {
  const { line } = cur
  cur.pos++ // opening quote
  let out = ''
  for (;;) {
    if (cur.pos >= line.length) cur.fail('unterminated string')
    const c = line[cur.pos]
    if (c === '"') {
      cur.pos++
      return out
    }
    if (c === '\\') {
      cur.pos++
      if (cur.pos >= line.length) cur.fail('unterminated string')
      const e = line[cur.pos]
      switch (e) {
        case '"':
          out += '"'
          cur.pos++
          break
        case '\\':
          out += '\\'
          cur.pos++
          break
        case 'n':
          out += '\n'
          cur.pos++
          break
        case 't':
          out += '\t'
          cur.pos++
          break
        case 'r':
          out += '\r'
          cur.pos++
          break
        case '0':
          out += '\0'
          cur.pos++
          break
        case 'u': {
          const hex = line.slice(cur.pos + 1, cur.pos + 5)
          if (hex.length !== 4 || !/^[0-9a-fA-F]{4}$/.test(hex)) {
            cur.fail('invalid escape \\u')
          }
          out += String.fromCharCode(parseInt(hex, 16))
          cur.pos += 5
          break
        }
        default:
          cur.fail(`invalid escape \\${e}`)
      }
      continue
    }
    out += c
    cur.pos++
  }
}

function scanLiteralString(cur) {
  const { line } = cur
  cur.pos++ // opening quote
  const idx = line.indexOf("'", cur.pos)
  if (idx === -1) cur.fail('unterminated string')
  const out = line.slice(cur.pos, idx)
  cur.pos = idx + 1
  return out
}

// --- names ---------------------------------------------------------------

function readName(cur) {
  const c = cur.peek()
  if (c === '"') return scanBasicString(cur)
  if (c === "'") return scanLiteralString(cur)
  if (isNameChar(c)) {
    const start = cur.pos
    while (isNameChar(cur.line[cur.pos])) cur.pos++
    return cur.line.slice(start, cur.pos)
  }
  cur.fail('expected a name')
}

function readDottedName(cur) {
  const names = []
  for (;;) {
    cur.skipWs()
    names.push(readName(cur))
    cur.skipWs()
    if (cur.peek() === '.') {
      cur.pos++
      continue
    }
    break
  }
  return names
}

// --- path helpers ----------------------------------------------------------

function appendKey(base, name) {
  return base === '' ? name : `${base}.${name}`
}

function appendIndex(base, idx) {
  return `${base}[${idx}]`
}

// --- stepping through intermediate table segments --------------------------

function stepInto(container, name, basePath, cur) {
  if (container.entries.has(name)) {
    const node = container.entries.get(name)
    if (node.kind === 'table') {
      return { node, path: appendKey(basePath, name) }
    }
    if (node.kind === 'array-of-tables') {
      const idx = node.items.length - 1
      return { node: node.items[idx], path: appendIndex(appendKey(basePath, name), idx) }
    }
    cur.fail(`${appendKey(basePath, name)} is not a table`)
  }
  const node = makeTable(false)
  container.entries.set(name, node)
  return { node, path: appendKey(basePath, name) }
}

// --- values ----------------------------------------------------------------

const INT_RE = /^[+-]?\d+(?:_\d+)*$/
const FLOAT_RE = /^[+-]?\d+(?:_\d+)*(?:(?:\.\d+(?:_\d+)*)(?:[eE][+-]?\d+(?:_\d+)*)?|(?:[eE][+-]?\d+(?:_\d+)*))$/

function readValue(cur, path) {
  cur.skipWs()
  const c = cur.peek()
  if (cur.atEnd() || c === ',' || c === ']' || c === '}') {
    cur.fail('expected a value')
  }
  if (c === '"') return makeScalar('string', scanBasicString(cur))
  if (c === "'") return makeScalar('string', scanLiteralString(cur))
  if (c === '[') {
    cur.pos++
    return readArray(cur, path)
  }
  if (c === '{') {
    cur.pos++
    return readInlineTable(cur, path)
  }
  const { line } = cur
  const start = cur.pos
  while (cur.pos < line.length && !isSpace(line[cur.pos]) && line[cur.pos] !== ',' && line[cur.pos] !== ']' && line[cur.pos] !== '}') {
    cur.pos++
  }
  const token = line.slice(start, cur.pos)
  if (token === 'true') return makeScalar('boolean', true)
  if (token === 'false') return makeScalar('boolean', false)
  if (INT_RE.test(token)) return makeScalar('integer', parseInt(token.replace(/_/g, ''), 10))
  if (FLOAT_RE.test(token)) return makeScalar('float', parseFloat(token.replace(/_/g, '')))
  cur.fail(`invalid value ${token}`)
}

function readArray(cur, path) {
  const arr = makeArray()
  cur.skipWs()
  if (cur.atEnd()) cur.fail('unterminated array')
  if (cur.peek() === ']') {
    cur.pos++
    return arr
  }
  let idx = 0
  for (;;) {
    cur.skipWs()
    const value = readValue(cur, appendIndex(path, idx))
    cur.skipWs()
    if (cur.atEnd()) cur.fail('unterminated array')
    const c = cur.peek()
    if (c !== ',' && c !== ']') cur.fail('trailing text after a value')
    arr.items.push(value)
    idx++
    if (c === ',') {
      cur.pos++
      cur.skipWs()
      if (cur.atEnd()) cur.fail('unterminated array')
      if (cur.peek() === ']') {
        cur.pos++
        return arr
      }
      continue
    }
    cur.pos++
    return arr
  }
}

function readInlineTable(cur, path) {
  const root = makeTable(true)
  cur.skipWs()
  if (cur.atEnd()) cur.fail('unterminated inline table')
  if (cur.peek() === '}') {
    cur.pos++
    return root
  }
  for (;;) {
    cur.skipWs()
    const names = readDottedName(cur)
    cur.skipWs()
    if (cur.atEnd() || cur.peek() !== '=') cur.fail('expected = in an inline table')
    cur.pos++
    cur.skipWs()

    let container = root
    let containerPath = path
    for (let i = 0; i < names.length - 1; i++) {
      const step = stepInto(container, names[i], containerPath, cur)
      container = step.node
      containerPath = step.path
    }
    const last = names[names.length - 1]
    const fullPath = appendKey(containerPath, last)

    const value = readValue(cur, fullPath)
    cur.skipWs()
    if (!cur.atEnd() && cur.peek() !== ',' && cur.peek() !== '}') cur.fail('trailing text after a value')
    if (container.entries.has(last)) cur.fail(`key ${fullPath} is defined twice`)
    container.entries.set(last, value)

    cur.skipWs()
    if (cur.atEnd()) cur.fail('unterminated inline table')
    const c = cur.peek()
    if (c === ',') {
      cur.pos++
      continue
    }
    if (c === '}') {
      cur.pos++
      return root
    }
    cur.fail('trailing text after a value')
  }
}

// --- headers -----------------------------------------------------------

function handleHeader(cur, ctx) {
  cur.pos++ // consume first '['
  let isArray = false
  if (cur.peek() === '[') {
    isArray = true
    cur.pos++
  }
  cur.skipWs()
  const names = readDottedName(cur)
  cur.skipWs()
  if (isArray) {
    if (cur.peek() !== ']' || cur.line[cur.pos + 1] !== ']') cur.fail('unterminated table header')
    cur.pos += 2
  } else {
    if (cur.peek() !== ']') cur.fail('unterminated table header')
    cur.pos += 1
  }
  cur.skipWs()
  if (!cur.atEnd()) cur.fail('trailing text after a table header')

  let container = ctx.root
  let containerPath = ''
  for (let i = 0; i < names.length - 1; i++) {
    const step = stepInto(container, names[i], containerPath, cur)
    container = step.node
    containerPath = step.path
  }
  const last = names[names.length - 1]
  const fullPath = appendKey(containerPath, last)

  if (isArray) {
    let arrNode
    if (container.entries.has(last)) {
      arrNode = container.entries.get(last)
      if (arrNode.kind !== 'array-of-tables') cur.fail(`${fullPath} is not an array of tables`)
    } else {
      arrNode = makeArrayOfTables()
      container.entries.set(last, arrNode)
    }
    const newTable = makeTable(true)
    arrNode.items.push(newTable)
    const idx = arrNode.items.length - 1
    ctx.current = newTable
    ctx.currentPath = appendIndex(fullPath, idx)
  } else {
    let node
    if (container.entries.has(last)) {
      node = container.entries.get(last)
      if (node.kind !== 'table') cur.fail(`${fullPath} is not a table`)
      if (node.explicit) cur.fail(`table ${fullPath} is defined twice`)
      node.explicit = true
    } else {
      node = makeTable(true)
      container.entries.set(last, node)
    }
    ctx.current = node
    ctx.currentPath = fullPath
  }
}

// --- key = value lines ----------------------------------------------------

function handleAssignment(cur, ctx) {
  const names = readDottedName(cur)
  cur.skipWs()
  if (cur.peek() !== '=') cur.fail('expected key = value')
  cur.pos++
  cur.skipWs()

  let container = ctx.current
  let containerPath = ctx.currentPath
  for (let i = 0; i < names.length - 1; i++) {
    const step = stepInto(container, names[i], containerPath, cur)
    container = step.node
    containerPath = step.path
  }
  const last = names[names.length - 1]
  const fullPath = appendKey(containerPath, last)

  const value = readValue(cur, fullPath)
  cur.skipWs()
  if (!cur.atEnd()) cur.fail('trailing text after a value')

  if (container.entries.has(last)) cur.fail(`key ${fullPath} is defined twice`)
  container.entries.set(last, value)
}

// --- top level -----------------------------------------------------------

function isBlankOrCommentOnly(line) {
  let i = 0
  while (i < line.length && isSpace(line[i])) i++
  if (i >= line.length) return true
  return line[i] === '#' || line[i] === ';'
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const ctx = { root: makeTable(true), current: null, currentPath: '' }
  ctx.current = ctx.root

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    if (isBlankOrCommentOnly(raw)) continue
    let start = 0
    while (isSpace(raw[start])) start++
    const cur = new Cursor(raw, start, lineNo)
    if (cur.peek() === '[') {
      handleHeader(cur, ctx)
    } else {
      handleAssignment(cur, ctx)
    }
  }

  return ctx.root
}
